use std::{time::{Duration,Instant},sync::{Arc,atomic::{AtomicUsize,Ordering}},ffi::c_void};use windows::{core::{PCWSTR,w},Win32::Networking::WinHttp::*};
#[derive(Clone)] pub struct HttpRequest{pub url:String,pub headers:Vec<(String,String)>,pub body:Vec<u8>,pub timeout:Duration,pub max_response_bytes:usize}
#[derive(Debug)] pub struct HttpResponse{pub status:u16,pub headers:Vec<(String,String)>,pub body:Vec<u8>}
#[derive(Debug,Clone,Copy)] pub enum HttpError{NotSent,Uncertain,ResponseTooLarge}
pub trait Transport:Send+Sync{fn send(&self,r:&HttpRequest)->std::result::Result<HttpResponse,HttpError>;}
pub struct WinHttpTransport;
pub fn parse_url(url:&str)->std::result::Result<(bool,String,u16,String),HttpError>{let(secure,rest)=if let Some(s)=url.strip_prefix("https://"){(true,s)}else if let Some(s)=url.strip_prefix("http://"){(false,s)}else{return Err(HttpError::NotSent)};let (auth,path)=rest.split_once('/').unwrap_or((rest,""));if auth.is_empty()||auth.contains(['@','#','\\','?'])||url.chars().any(|c|c.is_control())||url.contains('#'){return Err(HttpError::NotSent)}let(host,port)=if let Some((h,p))=auth.split_once(':'){(h,p.parse().map_err(|_|HttpError::NotSent)?)}else{(auth,if secure{443}else{80})};if !host.is_ascii(){return Err(HttpError::NotSent)}Ok((secure,host.to_ascii_lowercase(),port,format!("/{path}")))}
fn wide(s:&str)->Vec<u16>{s.encode_utf16().chain(Some(0)).collect()}
struct Handle(*mut c_void);impl Drop for Handle{fn drop(&mut self){unsafe{if !self.0.is_null(){let _=WinHttpCloseHandle(self.0);}}}}
struct RequestHandle{raw:*mut c_void,shared:Arc<AtomicUsize>}impl Drop for RequestHandle{fn drop(&mut self){if self.shared.compare_exchange(self.raw as usize,0,Ordering::SeqCst,Ordering::SeqCst).is_ok(){unsafe{let _=WinHttpCloseHandle(self.raw);}}}}
impl Transport for WinHttpTransport{fn send(&self,r:&HttpRequest)->std::result::Result<HttpResponse,HttpError>{let r=r.clone();let timeout=r.timeout;let shared=Arc::new(AtomicUsize::new(0));let other=shared.clone();let(tx,rx)=std::sync::mpsc::sync_channel(1);std::thread::spawn(move||{let _=tx.send(send_inner(&r,other));});match rx.recv_timeout(timeout){Ok(result)=>result,Err(_)=>{let raw=shared.swap(0,Ordering::SeqCst);if raw!=0{unsafe{let _=WinHttpCloseHandle(raw as *mut c_void);}}Err(HttpError::Uncertain)}}}}
fn send_inner(r:&HttpRequest,shared:Arc<AtomicUsize>)->std::result::Result<HttpResponse,HttpError>{let(secure,host,port,path)=parse_url(&r.url)?;let deadline=Instant::now()+r.timeout;unsafe{
 let session=Handle(WinHttpOpen(w!("NotifyRedirectNative/1.0"),WINHTTP_ACCESS_TYPE_AUTOMATIC_PROXY,PCWSTR::null(),PCWSTR::null(),0));if session.0.is_null(){return Err(HttpError::NotSent)}let ms=r.timeout.as_millis().min(i32::MAX as u128) as i32;WinHttpSetTimeouts(session.0,ms,ms,ms,ms).map_err(|_|HttpError::NotSent)?;
 let host=wide(&host);let connection=Handle(WinHttpConnect(session.0,PCWSTR(host.as_ptr()),port,0));if connection.0.is_null(){return Err(HttpError::NotSent)}let path=wide(&path);let raw=WinHttpOpenRequest(connection.0,w!("POST"),PCWSTR(path.as_ptr()),PCWSTR::null(),PCWSTR::null(),std::ptr::null(),if secure{WINHTTP_FLAG_SECURE}else{WINHTTP_OPEN_REQUEST_FLAGS(0)});if raw.is_null(){return Err(HttpError::NotSent)}shared.store(raw as usize,Ordering::SeqCst);let _request=RequestHandle{raw,shared};let redirect=WINHTTP_DISABLE_REDIRECTS;WinHttpSetOption(Some(raw),WINHTTP_OPTION_DISABLE_FEATURE,Some(&redirect.to_ne_bytes())).map_err(|_|HttpError::NotSent)?;
 let headers=r.headers.iter().map(|(k,v)|format!("{k}: {v}\r\n")).collect::<String>();let headers:Vec<u16>=headers.encode_utf16().collect();if Instant::now()>=deadline{return Err(HttpError::NotSent)}WinHttpSendRequest(raw,Some(&headers),Some(r.body.as_ptr().cast()),r.body.len() as u32,r.body.len() as u32,0).map_err(|_|HttpError::Uncertain)?;WinHttpReceiveResponse(raw,std::ptr::null_mut()).map_err(|_|HttpError::Uncertain)?;
 let mut status=0u32;let mut size=4;WinHttpQueryHeaders(raw,WINHTTP_QUERY_STATUS_CODE|WINHTTP_QUERY_FLAG_NUMBER,PCWSTR::null(),Some((&mut status as *mut u32).cast()),&mut size,std::ptr::null_mut()).map_err(|_|HttpError::Uncertain)?;
 let mut headers=vec![];let mut buf=[0u16;512];let mut len=(buf.len()*2)as u32;if WinHttpQueryHeaders(raw,WINHTTP_QUERY_CUSTOM,w!("Retry-After"),Some(buf.as_mut_ptr().cast()),&mut len,std::ptr::null_mut()).is_ok(){headers.push(("retry-after".into(),String::from_utf16_lossy(&buf[..len as usize/2]).trim_end_matches('\0').to_string()));}
 let mut body=vec![];loop{if Instant::now()>=deadline{return Err(HttpError::Uncertain)}let mut chunk=[0u8;4096];let mut read=0;WinHttpReadData(raw,chunk.as_mut_ptr().cast(),chunk.len()as u32,&mut read).map_err(|_|HttpError::Uncertain)?;if read==0{break}if body.len()+read as usize>r.max_response_bytes{return Err(HttpError::ResponseTooLarge)}body.extend_from_slice(&chunk[..read as usize]);}Ok(HttpResponse{status:status as u16,headers,body})}}
